import { Schema, model, Document, Types } from 'mongoose';

// One row per thing a learner's allowance counts (services/usageLimits.service.ts):
//   - 'trak-question': a message the learner sent that Trak answered. Trak's
//     own replies and automatic greetings are never counted, and a message
//     that fails on our side is never recorded.
//   - 'practice-generation': a brand-new practice question generated by AI
//     for this learner. Questions served from the bank are free.
// Kept about 400 days: allowances only look back a month, the rest is history.
export type UsageKind = 'trak-question' | 'practice-generation';

export interface IUsageEvent extends Document {
  userId: Types.ObjectId;
  kind: UsageKind;
  /** A Trak question paid for from a tutoring pack (the weekly allowance was used up). */
  bonus?: boolean;
  /** Which tutoring pack a bought question came out of. */
  packPurchaseId?: Types.ObjectId;
  createdAt: Date;
}

const usageEventSchema = new Schema<IUsageEvent>({
  userId: { type: Schema.Types.ObjectId, ref: 'User', required: true },
  kind: { type: String, enum: ['trak-question', 'practice-generation'], required: true },
  bonus: { type: Boolean },
  packPurchaseId: { type: Schema.Types.ObjectId, ref: 'TrakPackPurchase' },
  createdAt: { type: Date, default: Date.now, expires: 60 * 60 * 24 * 400 },
});

usageEventSchema.index({ userId: 1, kind: 1, createdAt: -1 });

export const UsageEvent = model<IUsageEvent>('UsageEvent', usageEventSchema, 'usageEvents');
